// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke-test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /Fe:aim_test.exe
//
// Exported surface:
//   bool  WorldToScreen(const Vec3& world, const ViewParams& vp, Vec2& out)
//       -- projects a world-space point to screen pixels; returns false when
//          the point is behind the camera.
//
//   Vec2  AimDelta(const Vec3* heads, int count,
//                  const ViewParams& vp, const SmoothParams& sp)
//       -- iterates entity head positions, picks the closest target inside the
//          240 px cone, and returns a smoothed (dx, dy) crosshair correction.

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cfloat>
#include <cstdint>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

struct Matrix4x4 {
    float m[4][4];
};

static inline Vec2 Vec2Sub(Vec2 a, Vec2 b)  { return { a.x - b.x, a.y - b.y }; }
static inline float Vec2Len(Vec2 v)          { return sqrtf(v.x * v.x + v.y * v.y); }

// ---------------------------------------------------------------------------
// View parameters
// ---------------------------------------------------------------------------

struct ViewParams {
    Matrix4x4 viewProj;   // combined view-projection matrix (row-major)
    float      screenW;   // viewport width  in pixels
    float      screenH;   // viewport height in pixels
};

// ---------------------------------------------------------------------------
// Smoothing parameters
// ---------------------------------------------------------------------------

struct SmoothParams {
    float smoothFactor;   // 0 < smoothFactor <= 1  (1 = instant, ~0.05 = slow)
    float coneRadiusPx;   // cone half-radius in pixels (default: 120 for 240 px)
};

// ---------------------------------------------------------------------------
// WorldToScreen
//   Multiplies `world` by the view-projection matrix, performs the perspective
//   divide, and maps NDC [-1, 1] to screen-space pixels.
//   Returns false if w <= 0 (behind the near plane).
// ---------------------------------------------------------------------------

bool WorldToScreen(const Vec3& world, const ViewParams& vp, Vec2& out)
{
    const Matrix4x4& m = vp.viewProj;

    float x = world.x * m.m[0][0] + world.y * m.m[1][0]
            + world.z * m.m[2][0] + m.m[3][0];
    float y = world.x * m.m[0][1] + world.y * m.m[1][1]
            + world.z * m.m[2][1] + m.m[3][1];
    float w = world.x * m.m[0][3] + world.y * m.m[1][3]
            + world.z * m.m[2][3] + m.m[3][3];

    if (w <= 0.0f)
        return false;

    float invW = 1.0f / w;
    float ndcX = x * invW;   // [-1, 1]
    float ndcY = y * invW;

    // NDC to pixels: origin at top-left, y axis down.
    out.x = (ndcX  + 1.0f) * 0.5f * vp.screenW;
    out.y = (1.0f  - ndcY) * 0.5f * vp.screenH;
    return true;
}

// ---------------------------------------------------------------------------
// AimDelta
//   Projects every head position in `heads[0..count-1]`.  Among those that
//   fall inside a circle of radius sp.coneRadiusPx centred on the crosshair
//   (screen centre), selects the one closest to the crosshair.
//
//   Returns the raw pixel delta scaled by sp.smoothFactor so the caller can
//   add it incrementally to the current cursor position:
//
//       cursor += AimDelta(heads, n, vp, sp);
//
//   Returns {0, 0} when no valid target is found in the cone.
// ---------------------------------------------------------------------------

Vec2 AimDelta(const Vec3* heads, int count,
              const ViewParams& vp, const SmoothParams& sp)
{
    if (!heads || count <= 0)
        return { 0.0f, 0.0f };

    const Vec2 crosshair = { vp.screenW * 0.5f, vp.screenH * 0.5f };
    const float coneR    = sp.coneRadiusPx;      // 120 px for a 240 px cone
    const float coneRSq  = coneR * coneR;

    Vec2  bestScreen  = { 0.0f, 0.0f };
    float bestDistSq  = FLT_MAX;
    bool  found       = false;

    for (int i = 0; i < count; ++i) {
        Vec2 screen;
        if (!WorldToScreen(heads[i], vp, screen))
            continue;

        Vec2  delta  = Vec2Sub(screen, crosshair);
        float distSq = delta.x * delta.x + delta.y * delta.y;

        if (distSq <= coneRSq && distSq < bestDistSq) {
            bestDistSq = distSq;
            bestScreen = screen;
            found      = true;
        }
    }

    if (!found)
        return { 0.0f, 0.0f };

    // Raw delta from crosshair to target, scaled by the smooth factor.
    Vec2 raw = Vec2Sub(bestScreen, crosshair);
    float sf = sp.smoothFactor;
    // Clamp to (0, 1] so we never overshoot or divide by zero.
    if (sf <= 0.0f) sf = 0.001f;
    if (sf >  1.0f) sf = 1.0f;

    return { raw.x * sf, raw.y * sf };
}

// ---------------------------------------------------------------------------
// Standalone smoke-test
//   cl /std:c++17 /DAIM_SMOKE aim.cpp /Fe:aim_test.exe && aim_test.exe
// ---------------------------------------------------------------------------

#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    // Build a trivial identity-ish view-projection that maps world Z forward.
    ViewParams vp = {};
    vp.screenW = 1920.0f;
    vp.screenH = 1080.0f;
    // Row-major: scale 1 on x/y, perspective on z, homogeneous w from z.
    vp.viewProj.m[0][0] = 1.0f;
    vp.viewProj.m[1][1] = 1.0f;
    vp.viewProj.m[2][2] = 1.0f;
    vp.viewProj.m[2][3] = 1.0f;  // w = z  (simple perspective)
    vp.viewProj.m[3][3] = 0.0f;

    // A head slightly above the horizon, 10 units out.
    Vec3 heads[] = {
        {  0.2f, 0.1f, 10.0f },   // near centre -- should be inside cone
        {  5.0f, 0.0f,  8.0f },   // far right    -- outside 120 px cone
    };

    SmoothParams sp;
    sp.smoothFactor  = 0.1f;
    sp.coneRadiusPx  = 120.0f;    // 240 px diameter

    Vec2 d = AimDelta(heads, 2, vp, sp);
    printf("AimDelta => (%.4f, %.4f)\n", (double)d.x, (double)d.y);

    // Verify WorldToScreen directly.
    Vec2 s;
    bool ok = WorldToScreen(heads[0], vp, s);
    printf("WorldToScreen => ok=%d  (%.1f, %.1f)\n", ok, (double)s.x, (double)s.y);

    return 0;
}
#endif // AIM_SMOKE
